import { z } from "zod";
import { objectIdSchema } from "./farmer.validator";

export const submitClaimSchema = z.object({
  advanceId: objectIdSchema,
  bagsClaimed: z
    .number("Bags claimed is required")
    .int("Bags claimed must be a whole number")
    .min(1, "Bags claimed must be at least 1")
    .max(100_000, "Bags claimed is unrealistically large"),
  // UUID generated by the client per submission attempt; resubmitting the
  // same form (retry, double-click) reuses the key and is rejected as a dup.
  idempotencyKey: z.uuid("Invalid idempotency key"),
});

// Portal-scoped: deliberately has no `farmerId` field (mirrors
// listMyAdvancesQuerySchema / listMyRepaymentsQuerySchema) — the controller
// forces farmerId from the authenticated token instead of parsing input.
export const listMyClaimsQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type SubmitClaimInput = z.infer<typeof submitClaimSchema>;
export type ListMyClaimsQuery = z.infer<typeof listMyClaimsQuerySchema>;
